/*
 * A256836  Primes of form n^2 + 4096.
 * https://oeis.org/A256836
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = the n-th prime of the form m^2 + 4096, where m starts at
 *            1
 * Range:     u8 none, u16 n <= 37, u32 n <= 4522, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Validated: standard, pass, 54 terms through n = 7831 (2026-11-03)
 * Helpers:   is_prime_u128, is_prime_u64, mem
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The sequence is generated by scanning m, testing if m^2+4096 is prime, and
   collecting those values in increasing order. */

#include <stdbool.h>
#include <stddef.h>
#include <stdlib.h>
#include <stdint.h>
#include <limits.h>
#include "../utils/is_prime_u128.h"
#include "../utils/is_prime_u64.h"
#include "../utils/mem.h"

/* -----------------  Generic primality test ------------------------ */
static bool isPrimeGeneric(seq_t n)
{
    /* all seq_t are unsigned; use the smallest type that fits */
    if ((seq_t)(ULLONG_MAX) >= n) {
        return is_prime_u64((uint64_t)n);
    }
#if defined(__SIZEOF_INT128__)
    return is_prime_u128((__uint128_t)n);
#else
    /* fallback: if seq_t > 64‑bit but no 128‑bit support,
       order the test as simple trial division up to sqrt */
    seq_t limit = 0;
    for (seq_t i = 2; i*i <= n; ++i) {
        if (n % i == 0) return false;
    }
    return true;
#endif
}

/* Returns the n-th prime of the form m^2 + 4096 (1‑based index). */
seq_t a(idx_t n)
{
    /* Cache of previously found primes.  Cache is shared over all calls. */
    static seq_t *cache   = NULL;   /* array of primes */
    static size_t cache_len = 0;    /* number of primes in cache          */
    static size_t cache_cap = 0;    /* current allocated capacity          */
    static idx_t next_m   = 1;      /* next value of m to test            */

    if (n == 0)
        return 0;                   /* undefined for n < 1 */

    /* Generate primes until we have at least n of them. */
    while (cache_len < (size_t)n) {
        seq_t candidate = (seq_t)next_m * (seq_t)next_m + (seq_t)4096;

        if (isPrimeGeneric(candidate)) {
            /* Grow storage if needed. */
            if (cache_len == cache_cap) {
                size_t new_cap = (cache_cap == 0) ? 16 : cache_cap * 2;
                seq_t *tmp = mem_resize(seq_t, cache, new_cap);
                if (!tmp)
                    return 0; /* allocation failure – return 0 as guard */
                cache = tmp;
                cache_cap = new_cap;
            }
            cache[cache_len++] = candidate;
        }
        ++next_m;
    }

    return cache[(size_t)n - 1];
}
